CREATE OR REPLACE FUNCTION public.claim_booster_legendaire()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_id    uuid;
  v_solde integer;
  v_prix  integer;
begin
  -- LA REPRISE : un légendaire déjà payé, ouvert, jamais scellé — le sien.
  -- ⚠️ SANS fenêtre de temps, contrairement à `ouvrir_booster` (§3) : l'index
  -- « au plus un noir non scellé » garantit qu'il y en a au plus UN, il a
  -- déjà été payé d'une pièce d'argent, et c'est lui que `etat_coffre()`
  -- compte dans `noirs_ouverts` (§5) pour tenir la porte du manège ouverte.
  -- Le rendre est la seule réponse qui ne perde pas d'argent.
  select id into v_id from public.user_boosters
   where user_id = auth.uid() and origine = 'legendaire'
     and opened_at is not null and card_id is null
   order by opened_at desc
   limit 1;
  if v_id is not null then
    return jsonb_build_object(
      'ouvert', true, 'booster_id', v_id, 'reprise', true,
      'solde_argent', public.solde_argent(), 'prix', 0::integer);
  end if;

  select coalesce((value)::int, 1) into v_prix
    from public.reward_rules where key = 'prix_booster_legendaire';
  v_prix := coalesce(v_prix, 1);
  v_solde := public.solde_argent();

  -- ⚠️ UN REFUS MÉTIER N'EST PAS UNE ERREUR SERVEUR : 200, avec le motif.
  if v_solde < v_prix then
    return jsonb_build_object(
      'ouvert', false, 'raison', 'argent_insuffisant'::text,
      'solde_argent', v_solde, 'prix', v_prix);
  end if;

  begin
    insert into public.user_boosters (user_id, origine, opened_at)
      values (auth.uid(), 'legendaire', now())
      returning id into v_id;
  exception when unique_violation then
    -- L'index « au plus un noir non scellé » a parlé : on le rend.
    select id into v_id from public.user_boosters
     where user_id = auth.uid() and origine = 'legendaire'
       and card_id is null
     limit 1;
    return jsonb_build_object(
      'ouvert', true, 'booster_id', v_id, 'reprise', true,
      'solde_argent', v_solde, 'prix', 0::integer);
  end;

  insert into public.coin_ledger (user_id, delta, raison, currency, booster_id)
    values (auth.uid(), -v_prix, 'ouverture_booster_noir', 'silver', v_id);

  return jsonb_build_object(
    'ouvert', true, 'booster_id', v_id, 'reprise', false,
    'solde_argent', public.solde_argent(), 'prix', v_prix);
end $function$

CREATE OR REPLACE FUNCTION public.claim_retour_quotidien()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_montant   integer;
  v_credite   boolean := true;
  v_jour      date;
begin
  -- 13-09 (première arrivée) : pas de +10 avant la première séance finie — la même
  -- règle que etat_coffre.retour_disponible, tenue ici pour qu'on ne puisse pas la contourner.
  if not exists (select 1 from public.workouts w where w.user_id = auth.uid() and w.ended_at is not null) then
    return jsonb_build_object(
      'credite', false, 'raison', 'premiere_seance_requise', 'montant', 0,
      'jour', public.jour_courant(),
      'sachets_convertis', public.convertis_transaction(),
      'solde', public.solde_or());
  end if;
  select coalesce((value)::text::integer, 10) into v_montant
    from public.reward_rules where key = 'pieces_retour_quotidien';
  v_jour := public.jour_courant();

  begin
    insert into public.coin_ledger (user_id, delta, raison, currency, jour)
    values (auth.uid(), v_montant, 'retour_quotidien', 'yellow', v_jour);
  exception when unique_violation then
    -- Déjà pris ce jour-là. Pas une erreur : le bouton Claim peut appeler sans
    -- savoir (un autre appareil a pu passer avant).
    v_credite := false;
  end;

  return jsonb_build_object(
    'credite',           v_credite,
    'montant',           case when v_credite then v_montant else 0 end,
    'jour',              v_jour,
    'sachets_convertis', public.convertis_transaction(),
    'solde',             public.solde_or());
end $function$

CREATE OR REPLACE FUNCTION public.cloturer_seance(p_workout uuid, p_series integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid(); w public.workouts; n integer; r jsonb;
begin
  if u is null then raise sqlstate 'PT401' using message='connexion_requise'; end if;
  if p_workout is null or p_series is null or p_series<0 then raise sqlstate 'PT400' using message='cloture_invalide'; end if;
  select * into w from public.workouts where id=p_workout for update;
  if not found then raise sqlstate 'PT503' using message='seance_a_synchroniser'; end if;
  if w.user_id<>u then raise sqlstate 'PT403' using message='seance_inaccessible'; end if;
  if w.ended_at is null or w.sync_complete_at is null then raise sqlstate 'PT503' using message='seance_a_synchroniser'; end if;
  if w.ended_at<w.started_at or w.ended_at>now()+interval '5 minutes' then raise sqlstate 'PT400' using message='dates_invalides'; end if;
  select count(*)::integer into n from public.strength_sets s join public.logged_exercises e on e.id=s.logged_exercise_id
    where e.workout_id=p_workout and e.user_id=u and s.user_id=u;
  -- p_series est un contrôle de complétude, jamais la source du montant.
  if n<>p_series then raise sqlstate 'PT503' using message='series_a_synchroniser'; end if;
  r:=public.cloturer_seance_validee_interne(p_workout,n);
  if r->>'booster_id' is null then r:=r||jsonb_build_object('booster_neuf',false); end if;
  return r||jsonb_build_object('series_verifiees',n);
end $function$

CREATE OR REPLACE FUNCTION public.cloturer_seance_brut(p_workout uuid, p_series integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_par_serie integer;
  v_pieces    integer;
  v_credite   boolean := true;
  v_rejeu     boolean := false;
  v_booster   uuid;
  v_neuf      boolean := true;
  v_argent    boolean := false;   -- tombée À CET APPEL
  v_argent_s  boolean := false;   -- tombée pour CETTE SÉANCE (le stocké)
  v_prix      integer;
  v_solde     integer;
begin
  if p_workout is null then
    raise exception 'cloturer_seance : il faut la séance';
  end if;

  select coalesce((value)::text::integer, 20) into v_par_serie
    from public.reward_rules where key = 'pieces_par_serie';
  v_pieces := greatest(coalesce(p_series, 0), 0) * v_par_serie;

  -- ① les pièces — seulement s'il y a eu du travail. L'insertion déclenche la
  --    conversion (§3) dans la même transaction.
  if v_pieces > 0 then
    begin
      insert into public.coin_ledger
        (user_id, delta, raison, currency, workout_id)
      values (auth.uid(), v_pieces, 'serie_faite', 'yellow', p_workout);
    exception when unique_violation then
      -- Un REJEU : l'index a parlé. On relit ce qui a été payé la première fois.
      v_credite := false;
      v_rejeu   := true;
      select coalesce(delta, 0) into v_pieces
        from public.coin_ledger
       where user_id = auth.uid() and raison = 'serie_faite' and workout_id = p_workout
       limit 1;
    end;
  else
    v_credite := false;
  end if;

  -- ② le sachet — FORFAITAIRE (un par séance terminée, quel que soit le
  --    nombre de séries).
  if greatest(coalesce(p_series, 0), 0) > 0 then
    begin
      insert into public.user_boosters (user_id, origine, workout_id)
      values (auth.uid(), 'seance', p_workout)
      returning id into v_booster;
    exception when unique_violation then
      v_neuf := false;
      select id into v_booster
        from public.user_boosters
       where user_id = auth.uid() and workout_id = p_workout
       limit 1;
    end;
  end if;

  -- ③ LA RARETÉ — au règlement, une seule fois, isolée dans une
  --    sous-transaction (le bonus ne coûte jamais le crédit principal).
  if v_credite then
    begin
      v_argent := public.roll_rare(p_workout);
    exception when others then
      v_argent := false;
    end;
  end if;
  -- Le stocké : cette séance a-t-elle (jamais) fait tomber sa pièce ?
  select exists (
    select 1 from public.coin_ledger
     where user_id = auth.uid() and raison = 'piece_argent' and workout_id = p_workout)
    into v_argent_s;

  select coalesce((value)::text::integer, 100) into v_prix
    from public.reward_rules where key = 'prix_booster';
  v_solde := public.solde_or();

  return jsonb_build_object(
    'pieces',            case when v_credite or v_rejeu then v_pieces else 0 end,
    'pieces_creditees',  v_credite,
    'rejeu',             v_rejeu,
    'booster_id',        v_booster,
    'booster_neuf',      v_neuf and v_booster is not null,
    'solde',             v_solde,
    'solde_argent',      public.solde_argent(),
    'argent',            v_argent,
    'argent_seance',     v_argent_s,
    'sachets_convertis', public.convertis_transaction(),
    'reste',             (greatest(v_solde, 0) % greatest(v_prix, 1))::int,
    'prix_booster',      v_prix);
end $function$

CREATE OR REPLACE FUNCTION public.cloturer_seance_validee_interne(p_workout uuid, p_series integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_reponse   jsonb;
  v_faits     jsonb;
  v_cardio    jsonb;
  v_total     integer := 0;
  v_credite   integer := 0;
  v_rejeu     boolean := false;
  v_bonus     integer := 0;
  v_bonus_val integer := public.regle_num('bonus_progres', 30)::integer;
  v_booster   uuid;
  v_sachet    boolean := false;
  v_prix      integer;
  v_solde     integer;
begin
  -- ① la clôture d'avant : les pièces des séries, le sachet (si p_series > 0), la pièce
  --    d'argent — idempotente, rejouée elle rend le stocké
  v_reponse := public.cloturer_seance_brut(p_workout, p_series);

  -- ② les faits (15-09 matin) — jamais une erreur pour un fait décoratif
  begin
    v_faits := public.calculer_faits_seance(p_workout);
  exception when others then
    v_faits := jsonb_build_object('faits', '[]'::jsonb, 'raison', 'calcul_impossible');
  end;

  -- ③ le cardio — APRÈS _brut : le déclencheur de conversion par 100 voit le total
  begin
    v_cardio := public.pieces_cardio_seance(p_workout);
  exception when others then
    v_cardio := jsonb_build_object('total', 0, 'exercices', '[]'::jsonb, 'raison', 'calcul_impossible');
  end;
  v_total := coalesce((v_cardio->>'total')::integer, 0);
  if v_total > 0 then
    begin
      insert into public.coin_ledger (user_id, delta, raison, currency, workout_id)
      values (auth.uid(), v_total, 'cardio_seance', 'yellow', p_workout);
      v_credite := v_total;
    exception when unique_violation then
      -- déjà payé : on relit ce qui l'a été la première fois, rien ne bouge
      v_rejeu := true;
      select coalesce(delta, 0) into v_credite
        from public.coin_ledger
       where user_id = auth.uid() and raison = 'cardio_seance' and workout_id = p_workout
       limit 1;
    end;

    -- le sachet forfaitaire qu'une séance SANS série n'avait pas (_brut l'exige > 0) :
    -- un par séance, l'index user_boosters_seance_unique en répond
    if coalesce(p_series, 0) <= 0 then
      begin
        insert into public.user_boosters (user_id, origine, workout_id)
        values (auth.uid(), 'seance', p_workout)
        returning id into v_booster;
        v_sachet := true;
      exception when unique_violation then
        select id into v_booster from public.user_boosters
         where user_id = auth.uid() and workout_id = p_workout limit 1;
      end;
      v_reponse := v_reponse || jsonb_build_object('booster_id', v_booster, 'booster_neuf', v_sachet);
    end if;

    -- ④ le bonus est une RÈGLE : un fait top_cardio rangé pour cette séance → bonus_progres,
    --    une ligne à part, idempotente par le même index
    if exists (select 1 from public.workout_facts f
                where f.user_id = auth.uid() and f.workout_id = p_workout and f.kind = 'top_cardio') then
      begin
        insert into public.coin_ledger (user_id, delta, raison, currency, workout_id)
        values (auth.uid(), v_bonus_val, 'bonus_progres', 'yellow', p_workout);
        v_bonus := v_bonus_val;
      exception when unique_violation then
        select coalesce(delta, 0) into v_bonus
          from public.coin_ledger
         where user_id = auth.uid() and raison = 'bonus_progres' and workout_id = p_workout
         limit 1;
      end;
    end if;
  end if;

  -- ⑤ le solde, le reste et les sachets convertis, RELUS après le crédit (ceux de _brut
  --    dataient d'avant le cardio — un coffre qui aurait menti d'une séance)
  select coalesce((value)::text::integer, 100) into v_prix from public.reward_rules where key = 'prix_booster';
  v_solde := public.solde_or();
  v_reponse := v_reponse || jsonb_build_object(
    'solde',             v_solde,
    'reste',             (greatest(v_solde, 0) % greatest(v_prix, 1)),
    'sachets_convertis', public.convertis_transaction());

  return v_reponse
      || jsonb_build_object('faits', coalesce(v_faits->'faits', '[]'::jsonb),
                            'faits_raison', v_faits->>'raison')
      || jsonb_build_object('pieces_cardio',  v_credite,
                            'cardio_detail',  v_cardio - 'total',
                            'cardio_rejeu',   v_rejeu,
                            'bonus_progres',  v_bonus,
                            'sachet_cardio',  v_sachet,
                            'pieces_total',   coalesce((v_reponse->>'pieces')::integer, 0) + v_credite + v_bonus);
end $function$

CREATE OR REPLACE FUNCTION public.convertir_pieces(p_user uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_prix    integer;
  v_solde   integer;
  v_n       integer := 0;
  v_booster uuid;
begin
  if p_user is null then return 0; end if;

  select coalesce((value)::text::integer, 100) into v_prix
    from public.reward_rules where key = 'prix_booster';
  v_prix := greatest(coalesce(v_prix, 100), 1);

  perform pg_advisory_xact_lock(hashtext(p_user::text));

  select coalesce(sum(delta), 0)::int into v_solde
    from public.coin_ledger
   where user_id = p_user and currency = 'yellow';

  while v_solde >= v_prix loop
    if v_n >= 1000 then
      raise warning 'convertir_pieces : borne atteinte pour %, il reste % pièces', p_user, v_solde;
      exit;
    end if;

    insert into public.user_boosters (user_id, origine)
    values (p_user, 'conversion')
    returning id into v_booster;

    insert into public.coin_ledger (user_id, delta, raison, currency, booster_id)
    values (p_user, -v_prix, 'conversion_booster', 'yellow', v_booster);

    v_n     := v_n + 1;
    v_solde := v_solde - v_prix;
  end loop;

  return v_n;
end $function$

CREATE OR REPLACE FUNCTION public.tirer_noeud_chemin(p_noeud integer, p_pieces boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare n integer; seuil integer;
begin
 if auth.uid() is null then raise sqlstate 'PT401' using message='connexion_requise'; end if;
 if p_noeud is null or p_noeud<0 or p_noeud>=45 or p_noeud%9 not in (3,8) then
   raise sqlstate 'PT400' using message='noeud_invalide'; end if;
 -- Un ancien claim reste rejouable ; aucun nouveau droit n'est inventé.
 if not exists(select 1 from public.noeuds_chemin_reclames() r where r.noeud_id=p_noeud) then
   select count(*) into n from public.seances_chemin();
   seuil:=(p_noeud/9)*7+case when p_noeud%9=3 then 3 else 7 end;
   if n<seuil then raise sqlstate 'PT409' using message='progression_insuffisante'; end if;
 end if;
 return public.tirer_noeud_chemin_valide_interne(p_noeud,p_pieces);
end $function$

CREATE OR REPLACE FUNCTION public.tirer_noeud_chemin_brut(p_noeud integer, p_pieces boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deja     boolean := false;
  v_montant  integer := 0;
  v_monnaie  text    := 'yellow';
  v_robes    text[]  := '{}';
  v_rarete   text    := 'common';
  v_secs     integer := 0;
  v_mult     numeric := 1;
  v_pitie    integer;
  v_min      integer;
  v_max      integer;
  v_t_noire  numeric;
  v_t_double numeric;
  v_t_rare   numeric;
  v_faits    integer := 0;
  v_robe     text;
  v_chap     integer;
  v_par      integer;
  v_milieu   integer;
  v_tresor   integer;
  v_rang     integer;
  v_chapitre integer;
begin
  if p_noeud is null then
    raise exception 'tirer_noeud_chemin : il faut le nœud';
  end if;

  -- ── LE NŒUD EST BORNÉ ET RAPPROCHÉ DE SA PISTE (relecture adverse 30-08) ──
  -- Sans ça, tout compte authentifié pouvait appeler (45, true), (46, true),
  -- … (10^9, true) : chaque entier neuf passait les index (user, nœud) et
  -- créditait 100-200 pièces — et 6 % de pièces d'argent. La géométrie du
  -- chemin vit DÉJÀ dans `reward_rules` (migration 20260829170000) : 5
  -- chapitres de 9 nœuds, la récompense du milieu au rang 3 (pièces si le
  -- chapitre est pair, lune = sachets s'il est impair), le trésor au rang 8.
  select coalesce((value)::int, 5) into v_chap
    from public.reward_rules where key = 'chemin_chapitres';
  select coalesce((value)::int, 9) into v_par
    from public.reward_rules where key = 'chemin_noeuds_par_chapitre';
  select coalesce((value)::int, 3) into v_milieu
    from public.reward_rules where key = 'chemin_rang_recompense_milieu';
  select coalesce((value)::int, 8) into v_tresor
    from public.reward_rules where key = 'chemin_rang_tresor';
  v_chap   := coalesce(v_chap, 5);
  v_par    := coalesce(v_par, 9);
  v_milieu := coalesce(v_milieu, 3);
  v_tresor := coalesce(v_tresor, 8);
  if p_noeud < 0 or p_noeud >= v_chap * v_par then
    return jsonb_build_object(
      'deja_reclame', false, 'raison', 'noeud_invalide'::text,
      'solde', public.solde_or(), 'solde_argent', public.solde_argent());
  end if;
  v_rang     := p_noeud % v_par;
  v_chapitre := p_noeud / v_par;
  if not ((v_rang = v_tresor and not p_pieces)
          or (v_rang = v_milieu and p_pieces = (v_chapitre % 2 = 0))) then
    return jsonb_build_object(
      'deja_reclame', false, 'raison', 'piste_invalide'::text,
      'solde', public.solde_or(), 'solde_argent', public.solde_argent());
  end if;

  -- ── DÉJÀ RÉCLAMÉ ? On rend ce qui a été tiré, tel quel. ──
  if p_pieces then
    select delta, currency into v_montant, v_monnaie
      from public.coin_ledger
     where user_id = auth.uid() and raison = 'chemin' and noeud_id = p_noeud
     limit 1;
    if found then
      return jsonb_build_object(
        'deja_reclame', true, 'type', 'coins'::text,
        'montant', v_montant, 'monnaie', v_monnaie,
        'robes', '[]'::jsonb,
        'rarete', case when v_monnaie = 'silver' then 'legendary'::text
                       else 'common'::text end,
        'solde', public.solde_or(), 'solde_argent', public.solde_argent());
    end if;
  else
    -- ⚠️ Les deux lignes naissent dans la MÊME transaction (même `now()`) :
    -- `obtained_at` ne les départage pas — la ligne `chemin` (première
    -- robe tirée) passe avant la ligne `cadeau`, comme au tirage.
    select array_agg(coalesce(robe, 'lune') order by (origine = 'cadeau'), obtained_at)
      into v_robes
      from public.user_boosters
     where user_id = auth.uid() and origine in ('chemin', 'cadeau')
       and noeud_id = p_noeud;
    if v_robes is not null and array_length(v_robes, 1) > 0 then
      return jsonb_build_object(
        'deja_reclame', true, 'type', 'boosters'::text,
        'montant', 0::integer, 'monnaie', 'yellow'::text,
        'robes', to_jsonb(v_robes),
        'rarete', case when 'noire' = all(v_robes) then 'legendary'::text
                       when 'noire' = any(v_robes) then 'rare'::text
                       else 'common'::text end,
        'solde', public.solde_or(), 'solde_argent', public.solde_argent());
    end if;
  end if;

  -- ── LES RÈGLES, lues en base (avec les défauts du client si absentes) ──
  select coalesce((value)::numeric, 0.06) into v_t_noire
    from public.reward_rules where key = 'chemin_taux_piece_noire';
  select coalesce((value)::numeric, 0.01) into v_t_double
    from public.reward_rules where key = 'chemin_taux_double_legendaire';
  select coalesce((value)::numeric, 0.11) into v_t_rare
    from public.reward_rules where key = 'chemin_taux_rare';
  select coalesce((value)::int, 12) into v_pitie
    from public.reward_rules where key = 'chemin_pitie';
  select coalesce((value)::int, 100) into v_min
    from public.reward_rules where key = 'chemin_pieces_min';
  select coalesce((value)::int, 200) into v_max
    from public.reward_rules where key = 'chemin_pieces_max';
  v_t_noire  := coalesce(v_t_noire, 0.06);
  v_t_double := coalesce(v_t_double, 0.01);
  v_t_rare   := coalesce(v_t_rare, 0.11);
  v_pitie    := coalesce(v_pitie, 12);
  v_min      := coalesce(v_min, 100);
  v_max      := coalesce(v_max, 200);

  -- ── LA PITIÉ, DÉRIVÉE : les communs d'affilée depuis le dernier non-commun ──
  if p_pieces then
    select count(*) into v_secs
      from public.coin_ledger cl
     where cl.user_id = auth.uid() and cl.raison = 'chemin'
       and cl.currency = 'yellow'
       and cl.created_at > coalesce(
         (select max(created_at) from public.coin_ledger
           where user_id = auth.uid() and raison = 'chemin'
             and currency = 'silver'),
         '-infinity'::timestamptz);
  else
    select count(distinct ub.noeud_id) into v_secs
      from public.user_boosters ub
     where ub.user_id = auth.uid() and ub.origine in ('chemin', 'cadeau')
       and ub.obtained_at > coalesce(
         (select max(obtained_at) from public.user_boosters
           where user_id = auth.uid() and origine in ('chemin', 'cadeau')
             and robe = 'noire'),
         '-infinity'::timestamptz);
  end if;
  -- La même courbe que le client : ×2 par nœud au-delà du seuil.
  v_mult := power(2::numeric, greatest(0, v_secs - v_pitie + 1));

  -- ── LE TIRAGE, ici et nulle part ailleurs ──
  if p_pieces then
    if random() < least(1::numeric, v_t_noire * v_mult) then
      v_montant := 1; v_monnaie := 'silver'; v_rarete := 'legendary';
    else
      v_montant := v_min + floor(random() * (v_max - v_min + 1))::int;
      v_monnaie := 'yellow'; v_rarete := 'common';
    end if;
    begin
      insert into public.coin_ledger (user_id, delta, raison, currency, noeud_id)
        values (auth.uid(), v_montant, 'chemin', v_monnaie, p_noeud);
    exception when unique_violation then
      -- LA COURSE (deux requêtes en vol, deux appareils) : l'index a parlé,
      -- on rend ce qui a été ÉCRIT par le gagnant — jamais le tirage neuf
      -- que l'index vient de refuser (relecture adverse 30-08).
      v_deja := true;
      select delta, currency into v_montant, v_monnaie
        from public.coin_ledger
       where user_id = auth.uid() and raison = 'chemin' and noeud_id = p_noeud
       limit 1;
      v_rarete := case when v_monnaie = 'silver' then 'legendary' else 'common' end;
    end;
    return jsonb_build_object(
      'deja_reclame', v_deja, 'type', 'coins'::text,
      'montant', v_montant, 'monnaie', v_monnaie,
      'robes', '[]'::jsonb, 'rarete', v_rarete,
      'solde', public.solde_or(), 'solde_argent', public.solde_argent());
  end if;

  if random() < least(1::numeric, v_t_double * v_mult) then
    v_robes := array['noire', 'noire']; v_rarete := 'legendary';
  elsif random() < least(1::numeric, v_t_rare * v_mult) then
    v_robes := array['lune', 'noire']; v_rarete := 'rare';
  else
    v_robes := array['lune', 'lune']; v_rarete := 'common';
  end if;
  -- Deux sachets sous un index (user, nœud) : la première robe fait la ligne
  -- du nœud, la seconde est un `cadeau` rattaché au même nœud — le
  -- contournement déjà en place, lisible et jamais dupliqué.
  foreach v_robe in array v_robes loop
    begin
      insert into public.user_boosters (user_id, origine, noeud_id, robe)
        values (auth.uid(),
                case when v_faits = 0 then 'chemin' else 'cadeau' end,
                p_noeud, v_robe);
      v_faits := v_faits + 1;
    exception when unique_violation then
      v_deja := true;
      exit;
    end;
  end loop;
  if v_deja then
    -- LA COURSE : on rend les robes ÉCRITES par le gagnant, pas les nôtres.
    -- ⚠️ Les deux lignes naissent dans la MÊME transaction (même `now()`) :
    -- `obtained_at` ne les départage pas — la ligne `chemin` (première
    -- robe tirée) passe avant la ligne `cadeau`, comme au tirage.
    select array_agg(coalesce(robe, 'lune') order by (origine = 'cadeau'), obtained_at)
      into v_robes
      from public.user_boosters
     where user_id = auth.uid() and origine in ('chemin', 'cadeau')
       and noeud_id = p_noeud;
    v_robes  := coalesce(v_robes, '{}');
    v_rarete := case when 'noire' = all(v_robes) then 'legendary'
                     when 'noire' = any(v_robes) then 'rare'
                     else 'common' end;
  end if;

  return jsonb_build_object(
    'deja_reclame', v_deja, 'type', 'boosters'::text,
    'montant', 0::integer, 'monnaie', 'yellow'::text,
    'robes', to_jsonb(v_robes), 'rarete', v_rarete,
    'solde', public.solde_or(), 'solde_argent', public.solde_argent());
end $function$
